// Lê o CSV do Protheus (binário 'data'), detecta o tipo do relatório e devolve as linhas.
// Dois relatórios, ambos CSV (separador ';'):
//   - OP/Empenhos + Transferência  -> colunas C2_PRODUTO / D4_COD / Soma de D4_QUANT / D4_XQTRANS
//   - Lista de Prioridades         -> colunas Mercado / MONTADOR / MÁQUINA / Situação / CLIENTE
const buf = await this.helpers.getBinaryDataBuffer(0, 'data');
let text = buf.toString('utf8');
if (((text.match(/\uFFFD/g) || []).length) > 3) text = buf.toString('latin1');
text = text.replace(/^\uFEFF/, '');
const lines = text.split(/\r?\n/).filter((l) => l.trim().length);
if (!lines.length) throw new Error('Arquivo vazio.');

const sniff = lines.slice(0, 8).join('\n');
const delim = ((sniff.split(';').length) >= (sniff.split(',').length)) ? ';' : ',';

function parseLine(line) {
  const out = []; let cur = ''; let q = false;
  for (let i = 0; i < line.length; i++) {
    const ch = line[i];
    if (q) {
      if (ch === '"') { if (line[i + 1] === '"') { cur += '"'; i++; } else q = false; }
      else cur += ch;
    } else {
      if (ch === '"') q = true;
      else if (ch === delim) { out.push(cur); cur = ''; }
      else cur += ch;
    }
  }
  out.push(cur);
  return out.map((s) => s.trim());
}

const headerRe = /D4_COD|C2_PRODUTO|Soma de D4_QUANT|D4_XQTRANS|D4_XQFALFI|MONTADOR|M[\u00c1A]QUINA|Mercado|Situa|CLIENTE|Data final acordada/i;
let h = 0;
for (let i = 0; i < lines.length; i++) { if (headerRe.test(lines[i])) { h = i; break; } }
const header = parseLine(lines[h]);

const rows = [];
for (let i = h + 1; i < lines.length; i++) {
  const cells = parseLine(lines[i]);
  if (cells.every((c) => c === '')) continue;
  const o = {};
  header.forEach((k, idx) => { if (k) o[k] = cells[idx] != null ? cells[idx] : ''; });
  rows.push(o);
}

const hj = header.join('|');
let tipo = null;
if (/D4_COD|Soma de D4_QUANT|C2_PRODUTO|D4_XQTRANS|D4_XQFALFI/i.test(hj)) tipo = 'op_empenhos';
else if (/MONTADOR|M[\u00c1A]QUINA|Mercado|Situa|CLIENTE|Data final acordada/i.test(hj)) tipo = 'prioridades';
if (!tipo) throw new Error('Não reconheci o relatório (esperado OP/Empenhos ou Prioridades).');

const bin = ($input.first().binary && $input.first().binary.data) || {};
const arquivo = bin.fileName || (tipo === 'op_empenhos' ? 'OP_Empenhos.csv' : 'Prioridades.csv');
return [{ json: { tipo, arquivo, total_linhas: rows.length, rows } }];
